{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/publication.py",
      "detail": "sync_batch_manifest reads Research checkpoints only from the current evidence epoch. After a new epoch begins, an unaffected article can retain its accepted global Research head while the manifest reports it as PENDING and not writing-ready. The new-epoch failure test uses placeholder heads rather than accepted prior-epoch checkpoints and asserts zero ready articles, so it does not verify the claimed readiness preservation.",
      "required_fix": "Resolve each manifest row from its current global Research head, including the originating epoch and verified completion record. Add an end-to-end test with two genuinely accepted prior heads and a failed transfer for one article; verify the other article’s status, readiness and manifest counts remain correct."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py; cloud_pilot/multilingual/localize.py",
      "detail": "The independent English review receives the entire writer packet, including writer-side skill and handoff assessments and similarity QA fields. Locale review also receives that packet as its English reference. This does not satisfy the requirement to exclude writer self-evaluation; the existing test checks only for a literal self_evaluation key.",
      "required_fix": "Build review inputs from an explicit allowlist of article content, immutable identity and source evidence, excluding writer-side assessments and QA conclusions. Test the actual English and locale review requests for exclusion while retaining the full evidence and rendered text."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
